insert into public.products (sku,slug,name,category_id,description,benefits,how_to_use,price,image_url) values
  ('SLM-P001','sprouted-health-mix','Sprouted Health Mix',(select id from public.categories where slug='organic-malt'),'A wholesome multi-grain sprouted health mix rich in protein, fibre and essential vitamins.','{"High Protein","Rich in Fibre","Energy Boosting"}','Mix 3 tbsp in 250ml warm milk. Sweeten with jaggery.',120,'assets/products/p1.jpg'),
  ('SLM-P002','badam-mix','Badam Mix',(select id from public.categories where slug='organic-malt'),'Premium almond-based health mix blended with traditional grains for complete nutrition.','{"Rich in Healthy Fats","Boosts Brain Health","Natural Energy"}','Mix 2 tbsp in warm milk or water. Best served hot.',160,'assets/products/p2.jpg'),
  ('SLM-P003','sprouted-ragi-choco-malt','Sprouted Ragi Choco Malt',(select id from public.categories where slug='organic-malt'),'The perfect blend of sprouted ragi with a touch of natural cocoa for a delicious health drink.','{"Rich in Calcium","Iron","Natural Chocolate Flavour"}','Mix 2 tbsp in 200ml warm milk. Kids love it!',95,'assets/products/p3.jpg'),
  ('SLM-P004','pasumanjal-malt','Pasumanjal Malt',(select id from public.categories where slug='organic-malt'),'Traditional turmeric-based malt with immunity-boosting properties.','{"Anti-Inflammatory","Immunity Booster","Traditional Recipe"}','Mix 2 tsp in warm milk with a pinch of pepper.',80,'assets/products/p4.jpg'),
  ('SLM-P005','sprouted-ragi-malt','Sprouted Ragi Malt',(select id from public.categories where slug='organic-malt'),'Pure sprouted finger millet malt — rich in calcium and a powerhouse of nutrition.','{"Rich in Calcium","Iron","Aids Digestion"}','Mix 2 tbsp in 200ml warm milk or water. Add honey to taste.',80,'assets/products/p5.svg'),
  ('SLM-P006','sprouted-homemade-horlicks','Sprouted Homemade Horlicks',(select id from public.categories where slug='organic-malt'),'Our homemade version of the classic malt drink, made with sprouted grains and natural ingredients.','{"Multi-Grain","No Artificial Additives","Complete Nutrition"}','Mix 3 tbsp in warm milk for a filling health drink.',110,'assets/products/p6.svg'),
  ('SLM-P007','sprouted-kambu-malt','Sprouted Kambu Malt',(select id from public.categories where slug='organic-malt'),'Pearl millet malt with cooling properties — ideal for summer and growing children.','{"Cooling","Iron-Rich","Gluten-Free"}','Mix 2 tbsp in water or milk. Add jaggery or palm sugar.',80,'assets/products/p7.svg'),
  ('SLM-P008','multi-millet-dosai-mix','Multi Millet Dosai Mix',(select id from public.categories where slug='organic-readymix'),'Premium multi-millet dosai mix for a healthy South Indian breakfast without compromise.','{"High Protein","Rich in Fibre","Multi-Grain"}','Mix with water to thin batter consistency. Cook on a hot tawa.',130,'assets/products/p8.svg'),
  ('SLM-P009','rava-dosai-mix','Rava Dosai Mix',(select id from public.categories where slug='organic-readymix'),'Instant crispy rava dosai mix — restaurant quality at home in minutes.','{"Instant","Crispy Texture","Traditional Taste"}','Mix with water. Add finely chopped onion and serve hot with chutney.',110,'assets/products/p9.svg'),
  ('SLM-P010','karuppakavuni-mix','Karuppakavuni Mix',(select id from public.categories where slug='organic-readymix'),'Black rice porridge mix with powerful antioxidants and traditional nutritional benefits.','{"Rich in Antioxidants","Anthocyanin-Rich","Traditional Superfood"}','Cook 1 cup with 3 cups water or milk. Sweeten with jaggery.',130,'assets/products/p10.svg'),
  ('SLM-P011','instant-pongal-mix','Instant Pongal Mix',(select id from public.categories where slug='organic-readymix'),'Traditional Tamil festival Pongal in an instant mix — tastes just like the real thing.','{"Festival Traditional","Ready in 15 mins","Authentic Flavour"}','Cook with water and ghee. Garnish with pepper and cashews.',120,'assets/products/p11.svg'),
  ('SLM-P012','ragi-dosai-mix','Ragi Dosai Mix',(select id from public.categories where slug='organic-readymix'),'Wholesome finger millet dosai mix — a nutritious alternative to regular rice dosai.','{"High Calcium","Iron","Great for Kids & Adults"}','Mix with water, rest 10 minutes. Cook on a non-stick tawa.',110,'assets/products/p12.jpg'),
  ('SLM-P019','thooyamalli-dosai-mix','Thooyamalli Dosai Mix',(select id from public.categories where slug='organic-readymix'),'Pure white ponni rice dosai mix with a soft texture and authentic traditional taste.','{"Soft Texture","Traditional Taste","No Preservatives"}','Mix with water to batter consistency. Ferment 2 hrs and cook on tawa.',110,'assets/products/p19.svg'),
  ('SLM-P020','ada-dosai-mix','Ada Dosai Mix',(select id from public.categories where slug='organic-readymix'),'Traditional Ada dosai mix made with rice and lentils for a thick, nutritious breakfast.','{"High Protein","Thick & Filling","Traditional Recipe"}','Mix with water, rest 30 minutes and cook on a greased tawa.',120,'assets/products/p20.svg'),
  ('SLM-P021','kambu-dosai-mix','Kambu Dosai Mix',(select id from public.categories where slug='organic-readymix'),'Pearl millet dosai mix — a cooling, iron-rich healthy breakfast option.','{"Cooling","Iron-Rich","Gluten-Friendly"}','Mix with water to batter consistency and cook fresh on tawa.',110,'assets/products/p21.svg'),
  ('SLM-P022','thinai-millet-dosai-mix','Thinai Millet Dosai Mix',(select id from public.categories where slug='organic-readymix'),'Foxtail millet dosai mix packed with iron and fibre for a wholesome breakfast.','{"Rich in Iron","High Fibre","Diabetic-Friendly"}','Mix with water, rest 10 minutes, and cook on a non-stick tawa.',110,'assets/products/p22.svg'),
  ('SLM-P023','kuthiraivali-millet-dosai-mix','Kuthiraivali Millet Dosai Mix',(select id from public.categories where slug='organic-readymix'),'Barnyard millet dosai mix — a light, digestible and nutritious morning meal.','{"Easy to Digest","Gluten-Free","Low Calorie"}','Mix with water and cook immediately on a hot tawa.',115,'assets/products/p23.svg'),
  ('SLM-P013','sambar-powder','Sambar Powder',(select id from public.categories where slug='organic-masala'),'Authentic homemade sambar powder with a perfect blend of hand-roasted spices.','{"Rich Aroma","Traditional Recipe","No Artificial Colours"}','Add 1–2 tsp per serving of sambar. Adjust to taste.',60,'assets/products/p13.jpg'),
  ('SLM-P014','biryani-masala','Biryani Masala',(select id from public.categories where slug='organic-masala'),'Premium homemade biryani masala with whole spices for an aromatic, authentic biryani.','{"Whole Spice Blend","Authentic Dum Flavour","No MSG"}','Use 2 tsp per kg rice. Add during cooking for best aroma.',70,'assets/products/p14.jpg'),
  ('SLM-P015','coriander-powder','Coriander Powder',(select id from public.categories where slug='organic-masala'),'Pure freshly ground coriander powder with an earthy, citrusy aroma.','{"Anti-Inflammatory","Improves Digestion","Natural Flavour"}','Use 1–2 tsp in gravies, curries, and marinades.',50,'assets/products/p15.svg'),
  ('SLM-P024','rasam-powder','Rasam Powder',(select id from public.categories where slug='organic-masala'),'Homemade rasam powder with a perfect tangy-spicy balance for comforting rasam.','{"Aids Digestion","Tangy Spice Blend","Traditional Taste"}','Add 1 tsp per serving of rasam. Adjust to taste.',55,'assets/products/p24.jpg'),
  ('SLM-P025','non-veg-masala','Non Veg Masala',(select id from public.categories where slug='organic-masala'),'Freshly ground non-veg masala with a rich blend of spices for chicken, mutton and fish.','{"Aromatic","Deep Flavour","No Artificial Colour"}','Marinate meat with 1–2 tsp masala. Cook as desired.',70,'assets/products/p25.jpg'),
  ('SLM-P026','turmeric-powder','Turmeric Powder',(select id from public.categories where slug='organic-masala'),'Pure sun-dried turmeric powder with a vibrant colour and strong anti-inflammatory properties.','{"Anti-Inflammatory","Immunity Boosting","Natural Colour"}','Add a pinch to curries, milk or rice for daily health benefits.',45,'assets/products/p26.svg'),
  ('SLM-P027','65-masala','65 Masala',(select id from public.categories where slug='organic-masala'),'Special spice blend for Chicken 65 and other crispy fry dishes — restaurant quality at home.','{"Bold & Spicy","Crispy Fry Blend","Authentic Taste"}','Mix with yogurt and meat. Marinate 30 mins. Deep fry or air fry.',65,'assets/products/p27.svg'),
  ('SLM-P028','cumin-powder','Cumin Powder',(select id from public.categories where slug='organic-masala'),'Freshly ground cumin powder with a warm, earthy aroma for everyday cooking.','{"Improves Digestion","Antioxidant-Rich","Natural Aroma"}','Add 1/2–1 tsp in gravies, rice dishes, and raitas.',50,'assets/products/p28.svg'),
  ('SLM-P016','varagu-laddu','Varagu Laddu',(select id from public.categories where slug='organic-laddu'),'Traditional kodo millet laddu sweetened with jaggery — a wholesome guilt-free sweet.','{"High Fibre","Low GI","Diabetic-Friendly"}','Enjoy 1–2 laddus as a healthy snack or dessert anytime.',95,'assets/products/p16.svg'),
  ('SLM-P017','thinai-laddu','Thinai Laddu',(select id from public.categories where slug='organic-laddu'),'Foxtail millet laddu with jaggery and ghee — energy-packed and nutritious.','{"Rich in Iron","Natural Energy","Traditional Sweet"}','Consume as a snack. Best enjoyed at room temperature.',95,'assets/products/p17.svg'),
  ('SLM-P018','kambu-laddu','Kambu Laddu',(select id from public.categories where slug='organic-laddu'),'Pearl millet laddu — a cooling, nutritious traditional sweet from Tamil Nadu.','{"Cooling Properties","Iron-Rich","Natural Sweetener"}','Have 1–2 laddus daily as a nutritious treat.',95,'assets/products/p18.svg'),
  ('SLM-P029','samai-laddu','Samai Laddu',(select id from public.categories where slug='organic-laddu'),'Little millet laddu with jaggery and ghee — light, digestible and traditionally nutritious.','{"Light & Digestible","Gluten-Free","Natural Energy"}','Have 1–2 laddus as a healthy snack any time of the day.',95,'assets/products/p29.svg'),
