-- ============================================================
-- SEED — real Sri Lakshmi Mart catalogue
-- Generated from the customer site data (js/data.js), so both
-- applications start from exactly the same products and prices.
-- Run after schema.sql. Re-runnable: conflicts are ignored.
-- ============================================================

on conflict (slug) do nothing;

on conflict (slug) do nothing;

-- size variants (organic foods)
on conflict (product_id,label) do nothing;

-- one inventory row per product; opening stock is 0 so the owner
-- enters real counts rather than inheriting invented numbers
select id, 10 from public.products on conflict do nothing;
